<?php
declare(strict_types=1); require_once __DIR__.'/includes/functions.php';
if (!installed()) redirect('/install.php'); if (!empty($_SESSION['user_id'])) redirect('/admin/');
$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $s=db()->prepare('SELECT * FROM users WHERE email=?'); $s->execute([trim($_POST['email']??'')]); $u=$s->fetch(); if($u && password_verify((string)($_POST['password']??''),$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];redirect('/admin/');} $error='Email ou mot de passe incorrect.';}
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Connexion</title><link rel="stylesheet" href="/public/css/app.css"></head><body><main class="auth"><section class="panel"><span class="badge">Administration</span><h1><?=e(setting('shop_name'))?></h1><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post"><label>Email<input type="email" name="email" required></label><label>Mot de passe<input type="password" name="password" required></label><button class="btn primary">Se connecter</button></form></section></main></body></html>